 const hostname = location.hostname.toLowerCase();
 const matches = domains => domains.some(d => hostname === d || hostname.endsWith('.' + d));
 const entries = Object.values(styles).filter(x => x.domains.some(matches));
 if (entries.length) {
  const media = matchMedia('(prefers-color-scheme: dark)');
  const style = document.createElement('style'); style.id = 'rose-pine-official';
  (document.head || document.documentElement).appendChild(style);
  const apply = () => { style.textContent = entries.flatMap(x => x.domains.map((d,i) => matches(d) ? x.variants[media.matches ? 'main' : 'dawn'][i] : '')).join('\n'); };
  media.addEventListener('change', apply); apply(); return;
 }
